#include <algorithm>
#include <functional>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <stdexcept>
#include <vector>
using namespace std;using U=unsigned long long;using G=vector<U>;using ll=long long;
void need(bool x,const char*s){if(!x)throw runtime_error(s);}bool arc(const G&a,int i,int j){return a[i]>>j&1;}
vector<vector<int>>autos(const G&a){int n=a.size();map<int,vector<int>>classes;for(int i=0;i<n;i++)classes[__builtin_popcountll(a[i])].push_back(i);vector<vector<int>>groups;for(auto [k,v]:classes)groups.push_back(v);vector<vector<int>>out;vector<int>p(n);function<void(int)>go=[&](int k){if(k==(int)groups.size()){for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(arc(a,i,j)!=arc(a,p[i],p[j]))return;out.push_back(p);return;}auto dest=groups[k];do{for(int i=0;i<(int)dest.size();i++)p[groups[k][i]]=dest[i];go(k+1);}while(next_permutation(dest.begin(),dest.end()));};go(0);return out;}
int main(){int graphs=0;ll words=0,fixed=0;for(int n=3;n<=14;n++){ll unrooted=0,rooted=0,conv=0,rootfixed=0,mass3=0,fibres=0;for(int d=0;2*d<=n-3;d++){int l=n-2-2*d;G a(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){bool forward=!(i==d&&j==d+l+1);a[forward?i:j]|=1ULL<<(forward?j:i);}for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(i!=j)need(arc(a,i,j)!=arc(a,n-1-i,n-1-j),"physical anti reflection");auto aut=autos(a);need(aut.size()==(l==1?3:1),"full automorphism order");int centralizer=0;for(auto&p:aut){bool commutes=1;for(int i=0;i<n;i++)commutes&=p[n-1-i]==n-1-p[i];centralizer+=commutes;}need(centralizer==1,"anti centralizer");vector<int>eligible;for(int i=d+(l>1);i<=d+l+(l==1);i++)eligible.push_back(i); // all three core vertices if l1, chain otherwise
set<set<int>>rootorbits,convorbits;for(int r:eligible){set<int>O,C;for(auto&p:aut){O.insert(p[r]);C.insert(p[r]);C.insert(n-1-p[r]);}rootorbits.insert(O);convorbits.insert(C);}need(rootorbits.size()==l&&convorbits.size()==(l+1)/2,"root and converse class orbits");int fixclasses=0;for(auto&O:rootorbits){set<int>rev;for(int r:O)rev.insert(n-1-r);fixclasses+=O==rev;}need(fixclasses==l%2,"fixed rooted classes");
ll H=0,F=0;set<G>normal;vector<int>path;auto dfs=[&](auto&&self,U mask,int last)->void{if(path.size()==(size_t)n){H++;bool fix=1;for(int i=0;i<n;i++)fix&=path[i]==n-1-path[n-1-i];if(fix){F++;G rows(n);for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(arc(a,path[i],path[j]))rows[i]|=1ULL<<j;normal.insert(rows);}return;}for(U q=a[last]&~mask;q;q&=q-1){U b=q&-q;path.push_back(__builtin_ctzll(b));self(self,mask|b,path.back());path.pop_back();}};for(int s=0;s<n;s++){path={s};dfs(dfs,1ULL<<s,s);}need(H==(1LL<<l)+1,"literal Hamilton count");ll want=l%2?1:(1LL<<(l/2))+1;need(F==want&&normal.size()==(size_t)want,"fixed words and exact normalized fibre");unrooted++;rooted+=rootorbits.size();conv+=convorbits.size();rootfixed+=fixclasses;mass3+=3/aut.size();fibres+=normal.size();graphs++;words+=H;fixed+=F;}
need(unrooted==(n-1)/2&&rooted==(n-1)*(n-1)/4,"summed class counts");int s=n/2;need(conv==(n%2?s*(s+1)/2:s*(s-1)/2),"summed converse orbits");need(rootfixed==(n%2?s:0),"summed fixed rooted classes");need(mass3==3*((n-1)/2)-2*(n%2),"unmarked orbit mass");need(fibres==(n%2?s:(1LL<<s)+s-3),"summed normalized fibres");cout<<"ORDER "<<n<<" unrooted "<<unrooted<<" rooted "<<rooted<<" converse "<<conv<<" rootfixed "<<rootfixed<<" mass_times3 "<<mass3<<" normalized_fibres "<<fibres<<"\n";}cout<<"PASS graphs "<<graphs<<" literal_Hamilton_words "<<words<<" fixed_words "<<fixed<<"\n";}
